// Compile-time request generator. GNU GPLv3; derived from buildcommands.py.
import {BuildMetadata} from './metadata.ts';
import {BuildCommands} from './commands.ts';
import {generateIdentify} from './identify.ts';
export const fileHeader = `
/* DO NOT EDIT! This is an autogenerated file. See scripts/buildcommands.mts. */

#include "board/irq.h"
#include "board/pgm.h"
#include "command.h"
#include "compiler.h"
#include "initial_pins.h"
`;
export function buildCommands(requests: string, kconfig: string, provenance: {version: string; toolstr: string}): {code: string; dictionary: string} {
  const metadata = new BuildMetadata(), commands = new BuildCommands();
  for (let line of requests.replaceAll('\r\n', '\n').replaceAll('\r', '\n').split('\n')) {
    line = line.trimStart();
    if (line && !metadata.accept(line) && !commands.accept(line)) throw new Error(`Unknown build time command '${line.split(/\s+/)[0]}'`);
  }
  const code = metadata.generate() + commands.generate();
  const identify = generateIdentify({...metadata.dictionary(), ...commands.dictionary(), version: provenance.version,
    build_versions: provenance.toolstr, app: 'Klipper', license: 'GNU GPLv3', kconfig: kconfig.replaceAll('\r\n','\n').replaceAll('\r','\n')});
  return {code: fileHeader + code + `\n// version: ${provenance.version}\n// build_versions: ${provenance.toolstr}\n` + identify.code, dictionary: identify.dictionary};
}
